class Solution {
    public String longestWord(String[] words){
        Set<String> dictionary=new HashSet<>(Arrays.asList(words));
        Arrays.sort(words);
        String answer="";
        for(String word:words){
            boolean valid=true;
            for(int end=1;end<word.length();end++)if(!dictionary.contains(word.substring(0,end))){
                valid=false;
                break;
            }
            if(valid&&word.length()>answer.length())answer=word;
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun longestWord(words:Array<String>):String{
        val dictionary=words.toHashSet();
        words.sort();
        var answer="";
        for(word in words){
            var valid=true;
            for(end in 1 until word.length)if(word.substring(0,end) !in dictionary){
                valid=false;
                break
            };
            if(valid&&word.length>answer.length)answer=word
        };
        return answer
    }
}

code.cpp:
class Solution {
    public: string longestWord(vector<string>& words){
        unordered_set<string> dictionary(words.begin(),words.end());
        sort(words.begin(),words.end());
        string answer;
        for(string& word:words){
            bool valid=true;
            for(int end=1;end<(int)word.size();++end)if(!dictionary.count(word.substr(0,end))){
                valid=false;
                break;
            }
            if(valid&&word.size()>answer.size())answer=word;
        }
        return answer;
    }
};
